import React, { useEffect, useState } from 'react';
import axios from 'axios';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import './DisplayTransaction.css';
import { Link } from 'react-router-dom';

const URL = "http://localhost:5000/transactions";

function DisplayTransactions() {
  const [transactions, setTransactions] = useState([]);
  const [filteredTransactions, setFilteredTransactions] = useState([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [suggestions, setSuggestions] = useState([]);

  useEffect(() => {
    fetchTransactions();
  }, []);

  const fetchTransactions = async () => {
    try {
      const res = await axios.get(URL);
      setTransactions(res.data.transactions);
      setFilteredTransactions(res.data.transactions);
    } catch (error) {
      console.error("Error fetching transactions", error);
    }
  };

  const deleteHandler = async (id) => {
    if (window.confirm("Are you sure you want to delete this transaction?")) {
      try {
        await axios.delete(`${URL}/${id}`);
        fetchTransactions();
      } catch (err) {
        console.error('Error deleting transaction:', err);
      }
    }
  };

  const handleSearchChange = (e) => {
    const query = e.target.value;
    setSearchQuery(query);

    if (!query.trim()) {
      setFilteredTransactions(transactions);
      setSuggestions([]);
      return;
    }

    const lowerQuery = query.toLowerCase();

    // Generate suggestions
    const suggestionSet = new Set();
    transactions.forEach((tx) => {
      Object.values(tx).forEach((val) => {
        const valStr = val?.toString().toLowerCase();
        if (valStr && valStr.includes(lowerQuery)) {
          suggestionSet.add(val.toString());
        }
      });
    });

    setSuggestions([...suggestionSet].slice(0, 5));

    // Filter transactions
    const filtered = transactions.filter((tx) =>
      Object.values(tx).some((val) =>
        val?.toString().toLowerCase().includes(lowerQuery)
      )
    );
    setFilteredTransactions(filtered);
  };

  const handleSuggestionClick = (value) => {
    setSearchQuery(value);
    setSuggestions([]);

    const filtered = transactions.filter((tx) =>
      Object.values(tx).some((val) =>
        val?.toString().toLowerCase().includes(value.toLowerCase())
      )
    );
    setFilteredTransactions(filtered);
  };

  //Generate PDF using jsPDF
  const handleDownloadPDF = () => {
    const doc = new jsPDF();

  // company logo as base64
   const logoDataUrl = 'data:image/png;base64,'; // Replace with your base64 logo string

  // Add logo
    doc.addImage(logoDataUrl, 'PNG', 10, 10, 40, 30);

  // Company name 
    doc.setFontSize(18);
    doc.setTextColor('#222');
    doc.setFont('helvetica', 'bold');
    doc.text('CraftLink', 60, 20);

  // Address and contact info 
    doc.setFontSize(11);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor('#555');
    doc.text('123 Main Street, Colombo, Sri Lanka', 60, 27);
    doc.text('Phone: (123) 456-7890 | Email: info@craftlink.com', 60, 34);

  // Draw a horizontal line under header
    doc.setDrawColor(0);
    doc.setLineWidth(0.5);
    doc.line(10, 45, 200, 45);

    doc.setFontSize(16);
    doc.text("Transaction Report", 14, 56);

    const tableColumn = ["Transaction ID", "Order ID", "User Type", "Amount", "Date", "Status"];
    const tableRows = [];

    filteredTransactions.forEach(tran => {
      const row = [
        tran.transaction_ID,
        tran.order_ID,
        tran.user_type,
        `LKR. ${tran.amount}`,
        new Date(tran.date).toLocaleDateString(),
        tran.status,
      ];
      tableRows.push(row);
    });

    if (tableRows.length === 0) {
      alert("No transactions to download.");
      return;
    }

    doc.autoTable({
      head: [tableColumn],
      body: tableRows,
      startY: 65,
    });

    doc.save("transaction_report.pdf");
  };

  return (
    <div className="transactions-container">
      <h2 className="transactions-title">Transaction Records</h2>

      <div className="add-btn-container no-print">
        <a href="/add-transaction" className="add-btn">
          + Add New
        </a>
      </div>

      <div className="search-container no-print">
        <input
          type="text"
          value={searchQuery}
          onChange={handleSearchChange}
          placeholder="Search transactions..."
          className="search-input"
        />
        {suggestions.length > 0 && (
          <ul className="suggestions-list">
            {suggestions.map((sugg, i) => (
              <li key={i} onClick={() => handleSuggestionClick(sugg)}>
                {sugg}
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className="table-wrapper">
        <table className="transactions-table">
          <thead>
            <tr>
              <th>Transaction ID</th>
              <th>Order ID</th>
              <th>User Type</th>
              <th>Amount</th>
              <th>Date</th>
              <th>Status</th>
              <th className="no-print">Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredTransactions.length > 0 ? (
              filteredTransactions.map((tran, i) => (
                <tr key={i}>
                  <td>{tran.transaction_ID}</td>
                  <td>{tran.order_ID}</td>
                  <td>{tran.user_type}</td>
                  <td>LKR. {tran.amount.toFixed(2)}</td>
                  <td>{new Date(tran.date).toLocaleDateString()}</td>
                  <td>{tran.status}</td>
                  <td className="no-print">
                    <Link to={`/view-transaction/${tran._id}`} className="btn view">View</Link>
                    <Link to={`/display-Transactions/${tran._id}`} className="btn edit">Edit</Link>
                    <button className="btn delete" onClick={() => deleteHandler(tran._id)}>
                      Delete
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="7">No transactions found.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <div className="no-print" style={{ marginTop: "20px" }}>
        <button onClick={handleDownloadPDF} className="add-btn">
          Download Report (PDF)
        </button>
      </div>
    </div>
  );
}

export default DisplayTransactions;
